-- Additive reporting metrics preserve historical answers during rolling deployment.
ALTER TABLE incidents
 ADD COLUMN IF NOT EXISTS process_experience integer CHECK (process_experience BETWEEN 1 AND 5),
 ADD COLUMN IF NOT EXISTS experience_person_name text,
 ADD COLUMN IF NOT EXISTS crew_response integer CHECK (crew_response BETWEEN 1 AND 5),
 ADD COLUMN IF NOT EXISTS site_conditions integer CHECK (site_conditions BETWEEN 1 AND 5);
--> statement-breakpoint
-- Upgrade only reviewed stock layouts; preserve tenant-designed documents.
DO $migration$
DECLARE tenant_row record;
BEGIN
 FOR tenant_row IN SELECT id FROM tenants LOOP
  PERFORM set_config('app.tenant_id', tenant_row.id::text, true);
  UPDATE pdf_templates SET source_html='<div style="font-family:-apple-system,''Segoe UI'',Roboto,Arial,sans-serif;color:#0f172a;"><div style="border-bottom:3px solid #0f172a;padding-bottom:8px;margin-bottom:10px;"><table style="width:100%;border-collapse:collapse;"><tr><td style="border:none;padding:0;"><h1 style="font-size:21px;font-weight:800;color:#0f172a;margin:0;letter-spacing:.2px;">Incident Report</h1><p style="font-size:12px;color:#64748b;margin:3px 0 0;">{{title}}</p></td><td style="border:none;padding:0;text-align:right;font-size:12px;color:#475569;vertical-align:top;">Reference <strong>{{reference}}</strong></td></tr></table></div><div style="margin:0 0 10px;"><span style="display:inline-block;border:1px solid #cbd5e1;background:#f1f5f9;color:#334155;border-radius:999px;padding:2px 10px;font-size:10px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;margin:0 6px 4px 0;">{{severity_label}}</span><span style="display:inline-block;border:1px solid #cbd5e1;background:#f1f5f9;color:#334155;border-radius:999px;padding:2px 10px;font-size:10px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;margin:0 6px 4px 0;">{{status_label}}</span><span style="display:inline-block;border:1px solid #cbd5e1;background:#f1f5f9;color:#334155;border-radius:999px;padding:2px 10px;font-size:10px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;margin:0 6px 4px 0;">{{type_label}}</span></div><table style="width:100%;border-collapse:collapse;"><tr><td style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">Reporting — General information</div></td></tr></table><table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><tr style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Occurred</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{occurred_at}}</td><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Reported</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{reported_at}}</td></tr><tr style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Site</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{site_name}}</td><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Location on site</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{location}}</td></tr><tr style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Department</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{department_name}}</td><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Weather</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{weather}}</td></tr><tr style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Supervisor</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{supervisor_name}}</td><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Foreman</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{foreman_text}}</td></tr><tr style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Reported by</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{reported_by_name}}</td><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Closed at</td><td style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{closed_at}}</td></tr><tr data-if="classification_labels" style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Classification</td><td colspan="3" style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{classification_labels}}</td></tr></table><table style="width:100%;border-collapse:collapse;margin:0 0 10px;"><tr data-if="events_leading_up" style="page-break-inside:auto;"><td style="border:none;padding:12px 0 0;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;break-after:avoid;page-break-after:avoid;">Events leading up to the incident</div><div style="border:1px solid #e2e8f0;border-left:3px solid #0f172a;background:#f8fafc;padding:8px 10px;font-size:11.5px;color:#0f172a;line-height:1.55;white-space:pre-wrap;margin-top:6px;">{{events_leading_up}}</div></td></tr></table><table style="width:100%;border-collapse:collapse;margin:0 0 10px;"><tr data-if="description" style="page-break-inside:auto;"><td style="border:none;padding:12px 0 0;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;break-after:avoid;page-break-after:avoid;">Event details / cause</div><div style="border:1px solid #e2e8f0;border-left:3px solid #0f172a;background:#f8fafc;padding:8px 10px;font-size:11.5px;color:#0f172a;line-height:1.55;white-space:pre-wrap;margin-top:6px;">{{description}}</div></td></tr></table><table style="width:100%;border-collapse:collapse;margin:0 0 10px;"><tr data-if="immediate_action_taken" style="page-break-inside:auto;"><td style="border:none;padding:12px 0 0;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;break-after:avoid;page-break-after:avoid;">Immediate action taken</div><div style="border:1px solid #e2e8f0;border-left:3px solid #0f172a;background:#f8fafc;padding:8px 10px;font-size:11.5px;color:#0f172a;line-height:1.55;white-space:pre-wrap;margin-top:6px;">{{immediate_action_taken}}</div></td></tr></table><table style="width:100%;border-collapse:collapse;margin:0 0 10px;"><tr data-if="ppe_worn" style="page-break-inside:auto;"><td style="border:none;padding:12px 0 0;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;break-after:avoid;page-break-after:avoid;">PPE worn</div><div style="border:1px solid #e2e8f0;border-left:3px solid #0f172a;background:#f8fafc;padding:8px 10px;font-size:11.5px;color:#0f172a;line-height:1.55;white-space:pre-wrap;margin-top:6px;">{{ppe_worn}}</div></td></tr></table><table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:50%" /><col style="width:50%" /></colgroup><thead><tr data-if="people_involved"><td colspan="2" style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">People involved</div></td></tr><tr data-if="people_involved"><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Name</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Role</th></tr></thead><tr data-each="people_involved" style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{name}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{role}}</td></tr></table><table style="width:100%;border-collapse:collapse;"><tr data-if="witnesses"><td style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">Witnesses & external parties</div></td></tr></table><table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><tr data-if="external_people_involved" style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">External people involved</td><td colspan="3" style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{external_people_involved}}</td></tr><tr data-if="witnesses" style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Witnesses</td><td colspan="3" style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{witnesses}}</td></tr></table><table style="width:100%;border-collapse:collapse;"><tr><td style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">Medical & regulatory</div></td></tr></table><table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><tr data-if="critical_injury" style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Critical injury</td><td colspan="3" style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">Yes</td></tr><tr data-if="ministry_of_labour_notified" style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">{{regulatory_authority_name}} notified</td><td colspan="3" style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">Yes</td></tr><tr data-if="ems_notified" style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">EMS notified</td><td colspan="3" style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">Yes</td></tr><tr data-if="externally_reportable" style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Externally reportable</td><td colspan="3" style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">Yes</td></tr><tr data-if="first_aid_received" style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">First aid received</td><td colspan="3" style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">Yes — provider: {{first_aid_provider}}</td></tr><tr data-if="medical_attention_received" style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Medical attention</td><td colspan="3" style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">Yes — treated at {{treated_at_hospital}}, {{treated_in_city}} · transport: {{transportation}}</td></tr><tr data-if="lost_time" style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Lost time</td><td colspan="3" style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{lost_time_first_day}} → {{lost_time_last_day}} ({{lost_time_days}} days)</td></tr><tr data-if="modified_duty" style="page-break-inside:avoid;"><td style="width:18%;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10.5px;font-weight:600;color:#475569;vertical-align:top;">Modified duty</td><td colspan="3" style="width:32%;border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{modified_duty_first_day}} → {{modified_duty_last_day}} ({{modified_duty_days}} days)</td></tr></table><table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:15.333333333333334%" /><col style="width:15.333333333333334%" /><col style="width:15.333333333333334%" /><col style="width:15.333333333333334%" /><col style="width:15.333333333333334%" /><col style="width:15.333333333333334%" /><col style="width:8%" /></colgroup><thead><tr data-if="injuries"><td colspan="7" style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">Injuries</div></td></tr><tr data-if="injuries"><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Person</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Body part(s)</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Injury type(s)</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Result / outcome</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Treatment</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Facility</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;