rder-bottom:2px solid #0f172a;padding-bottom:3px;">Investigation events</div></td></tr>{{/if}}{{#if events}}<tr><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:18%;">When</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Description</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:18%;">Recorded by</th></tr>{{/if}}</thead>{{#each events}}<tr style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:18%;">{{occurred_at}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{description}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:18%;">{{recorded_by_name}}</td></tr>{{/each}}</table><table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:8%" /><col style="width:92%" /></colgroup><thead>{{#if cause_analysis}}<tr><td colspan="2" style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">Cause analysis — investigator / H&S (5 Whys)</div></td></tr>{{/if}}{{#if cause_analysis}}<tr><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:8%;">Why</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Analysis</th></tr>{{/if}}</thead>{{#each cause_analysis}}<tr style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:8%;">{{ordinal}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{description}}</td></tr>{{/each}}</table><table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:24%" /><col style="width:76%" /></colgroup><thead>{{#if contributing_factors}}<tr><td colspan="2" style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">Contributing factors</div></td></tr>{{/if}}{{#if contributing_factors}}<tr><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:24%;">Category</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Description</th></tr>{{/if}}</thead>{{#each contributing_factors}}<tr style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:24%;">{{category}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{description}}</td></tr>{{/each}}</table><table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:4%" /><col style="width:56%" /><col style="width:16%" /><col style="width:12%" /><col style="width:12%" /></colgroup><thead>{{#if preventative_steps}}<tr><td colspan="5" style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">Preventative steps</div></td></tr>{{/if}}{{#if preventative_steps}}<tr><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:4%;">#</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Description</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:16%;">Owner</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:12%;">Target</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;width:12%;">Status</th></tr>{{/if}}</thead>{{#each preventative_steps}}<tr style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:4%;">{{@number}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;">{{description}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:16%;">{{owner_name}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:12%;">{{target_date}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;width:12%;">{{status}}</td></tr>{{/each}}</table>{{#if photos}}<div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;margin:14px 0 8px;break-after:avoid;page-break-after:avoid;">Photos</div>
    <div style="font-size:0;">{{#each photos}}<div style="display:inline-block;vertical-align:top;width:48%;margin:0 2% 10px 0;page-break-inside:avoid;">
      <img src="{{url}}" style="display:block;width:100%;height:210px;object-fit:contain;border:1px solid #e2e8f0;" alt="" />
      <div style="font-size:10px;color:#64748b;white-space:pre-wrap;overflow-wrap:anywhere;padding-top:3px;">{{caption}}</div>
    </div>{{/each}}</div>{{/if}}<table style="width:100%;border-collapse:collapse;margin-top:16px;"><tr style="page-break-inside:avoid;"><td style="border:none;padding:14px 0 6px;"><div style="font-size:13px;font-weight:700;color:#0f172a;text-transform:uppercase;letter-spacing:.6px;margin:0;border-bottom:2px solid #0f172a;padding-bottom:3px;">Sign-off</div><table style="width:100%;border-collapse:collapse;"><tr><td style="border:none;padding:34px 18px 0 0;"><div style="border-top:1.5px solid #334155;padding-top:4px;font-size:9.5px;color:#64748b;text-transform:uppercase;letter-spacing:.4px;">Signature</div></td><td style="border:none;padding:34px 18px 0 0;"><div style="border-top:1.5px solid #334155;padding-top:4px;font-size:9.5px;color:#64748b;text-transform:uppercase;letter-spacing:.4px;">Investigator / Supervisor</div></td><td style="border:none;padding:34px 18px 0 0;"><div style="border-top:1.5px solid #334155;padding-top:4px;font-size:9.5px;color:#64748b;text-transform:uppercase;letter-spacing:.4px;">Date signed</div></td></tr></table></td></tr></table></div>', updated_at=now()
  WHERE tenant_id=tenant_row.id AND key='incident-report-pdf' AND deleted_at IS NULL
    AND md5(source_html) IN ('06c8b1239594e2674c748e5809edea9d','b9391b6afeddc62a2ebbaed5dfaaf90d');
 END LOOP;
 PERFORM set_config('app.tenant_id', '', true);
END;
